const $=s=>document.querySelector(s);const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const read=(k,f)=>{try{return JSON.parse(localStorage.getItem(k)||'')}catch{return f}},write=(k,v)=>localStorage.setItem(k,JSON.stringify(v));
const slotNames=['早餐','上午','午餐','下午','晚餐','晚上'],slotIcons=['🍳','🌅','🍜','☀️','🍽️','🌙'];
const makePlanItem=(value,meta='點擊可修改',time='',done=false)=>({value,meta,time,done});
const defaultSlots=()=>slotNames.map((n,i)=>({name:n,icon:slotIcons[i],items:i===0?[makePlanItem('飯店早餐','住宿 / 附近早餐')]:[]}));
function normalizeSlots(list){return slotNames.map((n,i)=>{const src=Array.isArray(list)?list[i]:null;if(src&&Array.isArray(src.items))return{name:typeof src.name==='string'?src.name:n,icon:slotIcons.includes(src.icon)?src.icon:slotIcons[i],items:src.items.filter(Boolean).map(x=>({value:String(x.value??''),meta:String(x.meta??''),time:String(x.time??''),done:!!x.done})).filter(x=>x.value&&x.value!=='待安排')};if(src&&typeof src.value==='string'&&src.value&&src.value!=='待安排')return{name:typeof src.name==='string'?src.name:n,icon:slotIcons.includes(src.icon)?src.icon:slotIcons[i],items:[makePlanItem(src.value,String(src.meta??''),String(src.time??''),!!src.done)]};return{name:n,icon:slotIcons[i],items:[]}})}
function normalizePlans(plans){const out={};for(const [d,list]of Object.entries(plans||{}))out[d]=normalizeSlots(list);return out}
