const state={tab:'today',day:1,days:read('okinawa-days',5),plans:read('okinawa-plans',{}),flights:read('okinawa-flights',{outbound:{},return:{}}),stays:read('okinawa-stays',[]),meta:read('okinawa-meta',{startDate:'',endDate:'',transport:'自駕',rentalCompany:'',pickup:'',dropoff:'',budgetTarget:120000}),party:read('okinawa-party',[{name:'旅伴 1',type:'成人',age:'',notes:''},{name:'旅伴 2',type:'成人',age:'',notes:''},{name:'小朋友',type:'兒童',age:'3',notes:''}]),family:read('okinawa-family',{toddler:true,elderly:false,stroller:true,nap:true,relaxed:true}),expenses:read('okinawa-expenses',Object.fromEntries(expenseNames.map(x=>[x,0]))),weatherDays:{},explore:{q:'',filter:'全部',online:null,loading:false,error:'',selected:null,adding:false},custom:read('okinawa-custom-places',[]),hidden:read('okinawa-hidden-places',[]),modal:null,ai:null,entryQrs:{},insurance:read('okinawa-insurance',{company:'',policyNo:'',assistPhone:'',claimPhone:'',claimUrl:'',memo:''}),checklist:read('okinawa-checklist',checklistDefaults.map(x=>({...x,done:false})))};
if(!state.meta.startDate&&state.flights.outbound?.date){state.meta.startDate=state.flights.outbound.date;write('okinawa-meta',state.meta)}if(!state.meta.endDate&&state.flights.return?.date){state.meta.endDate=state.flights.return.date;write('okinawa-meta',state.meta)}
