let qrDbPromise;
function qrDb(){if(qrDbPromise)return qrDbPromise;qrDbPromise=new Promise((resolve,reject)=>{const r=indexedDB.open('okinawa-trip-local',1);r.onupgradeneeded=()=>{const db=r.result;if(!db.objectStoreNames.contains('entryQrs'))db.createObjectStore('entryQrs')};r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)});return qrDbPromise}
