function wxText(c){return c===0?'晴朗':c<=3?'晴時多雲':c<=48?'陰／霧':c<=67?'有雨':c<=82?'陣雨':'雷雨'}
function okinawaToday(){return new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Tokyo',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date())}
function daysUntil(date){if(!date)return null;return Math.round((Date.parse(date+'T00:00:00Z')-Date.parse(okinawaToday()+'T00:00:00Z'))/86400000)}
function dateForDay(d){if(!state.meta.startDate)return'';const x=new Date(state.meta.startDate+'T12:00:00Z');x.setUTCDate(x.getUTCDate()+d-1);return x.toISOString().slice(0,10)}
function wxForDay(d){const date=dateForDay(d),blank={temp:'--',text:'尚無預報',rain:'--'};if(!date)return{morning:blank,afternoon:blank,evening:blank,note:'尚未設定出發日',status:'unset'};const z=state.weatherDays[date]||{},keys=Object.keys(state.weatherDays).sort(),available=!!(z.morning||z.afternoon||z.evening),delta=daysUntil(date);let note='',status='unavailable';if(available){note='即時預報 · Open-Meteo';status='available'}else if((keys.length&&date>keys.at(-1))||(!keys.length&&delta>16)){note='天氣預報尚未開放';status='future'}else if(keys.length&&date<keys[0]){note='此日期已超出目前預報資料';status='past'}else note=navigator.onLine?'目前暫無此日預報':'目前離線，顯示已快取資料';return{morning:z.morning||blank,afternoon:z.afternoon||blank,evening:z.evening||blank,note,status}}
function today(){const t=trip(),all=t.flatMap(s=>s.items),done=all.filter(x=>x.done).length,total=all.length,tripDate=dateForDay(state.day),wf=wxForDay(state.day),countdown=daysUntil(state.meta.startDate);const heroWeather=wf.status==='available'?'<span>FORECAST</span><b>早 · 午 · 晚</b><span>分時天氣</span>':wf.status==='future'&&countdown!==null&&countdown>0?`<span>TRIP STARTS IN</span><b>${countdown} DAYS</b><span>天氣預報尚未開放</span>`:wf.status==='unset'?'<span>TRIP DATE</span><b>尚未設定</b><span>TRIP → 航班</span>':'<span>FORECAST</span><b>暫無資料</b><span>行程日期已保留</span>';const weatherBody=wf.status==='available'?`<div class="weatherStrip">${[['🌅','早上',wf.morning],['☀️','下午',wf.afternoon],['🌙','晚上',wf.evening]].map(([ic,n,w])=>`<div class="weatherPart"><span>${ic} ${n}</span><b>${w.temp}</b><small>${w.text} · 雨 ${w.rain}%</small></div>`).join('')}</div><div class="forecastNote">${esc(wf.note)}</div>`:`<div class="weatherPending"><b>${wf.status==='unset'?'📅 請先設定出發日':'🌤️ '+esc(wf.note)}</b><span>${wf.status==='unset'?'到 TRIP → FLIGHTS 設定去程日期後，DAY 1 會固定使用出發日。':'行程日期固定依出發日計算，不會被「今天」或天氣 API 範圍改掉。'}</span></div>`;return `${dayTabs()}<div class="hero"><div><b>DAY ${state.day}</b><span>${tripDate?tripDate+' · 沖繩':'出發日尚未設定 · 沖繩'}</span></div><div class="weather">${heroWeather}</div></div>${weatherBody}<div class="quick"><span>🚗 今日行程 · 6 時段</span><span class="ok">✓ ${done}/${total} 完成</span></div><progress class="progressBar" max="100" value="${total?done/total*100:0}"></progress><div class="slotGroups">${t.map((slot,si)=>`<section class="slotGroup"><div class="slotGroupHead"><div class="slotGroupTitle"><span class="slotGroupIcon">${esc(slot.icon)}</span><div><small>${esc(slot.name)}</small><b>${slot.items.length?slot.items.length+' 個行程':'尚未安排'}</b></div></div><button class="slotAdd" data-click="app.addSlotItem(${si})" aria-label="新增${esc(slot.name)}行程">＋</button></div><div class="slotItems">${slot.items.length?slot.items.map((item,ii)=>`<div class="slotItem ${item.done?'done':''}"><button class="check ${item.done?'checked':''}" data-click="app.toggleItem(${si},${ii})">${item.done?'✓':''}</button><div class="slotItemBody" data-click="app.editSlotItem(${si},${ii})"><small>${item.time?esc(item.time):'行程 '+(ii+1)}</small><b>${esc(item.value)}</b><span>${esc(item.done?'已完成':item.meta||'點擊可修改')}</span></div><div class="itemOrder"><button data-click="app.moveSlotItem(${si},${ii},-1)" ${ii===0?'disabled':''} aria-label="往上">↑</button><button data-click="app.moveSlotItem(${si},${ii},1)" ${ii===slot.items.length-1?'disabled':''} aria-label="往下">↓</button></div><button class="itemChevron" data-click="app.editSlotItem(${si},${ii})" aria-label="編輯">›</button></div>`).join(''):`<button class="emptySlot" data-click="app.addSlotItem(${si})">＋ 加入${esc(slot.name)}行程</button>`}</div></section>`).join('')}</div>${state.ai?.applied?`<div class="notice">✨ 已套用 SMART 免費行程，可逐天微調。</div>`:''}`}
