function tripView(){const total=Object.values(state.expenses).reduce((a,b)=>a+Number(b||0),0),staySub=state.stays.length?state.stays.map(s=>`D${s.fromDay}–${s.toDay} ${s.hotel||'未命名'}`).join(' · '):'可設定不同 Day 住不同飯店';return `<button class="aiLaunch" data-click="app.openAI()"><span class="lead">✨</span><div><small>SMART PLAN · FREE</small><b>免費智慧規劃整趟行程</b><span>本機運算 · 不用信用卡 · 不呼叫付費 AI</span></div><span>›</span></button>${card('✈️','FLIGHTS',state.flights.outbound?.flight||state.flights.return?.flight?'航班已設定':'設定去程 / 回程航班',state.flights.outbound?.flight?`去 ${state.flights.outbound.flight} ${state.flights.outbound.departTime||''} · 回 ${state.flights.return?.flight||'待設定'}`:'日期、機場、起降時間','flight')}${card('🏨','STAY',state.stays.length?`${state.stays.length} 間住宿`:'設定住宿',staySub,'stay')}${card('🚗','TRANSPORT',state.meta.transport||'自駕',state.meta.rentalCompany||'點此設定租車 / 包車','transport')}${card('👨‍👩‍👦','TRAVEL PARTY',state.party.map(p=>p.type+(p.age?' '+p.age+'歲':'')).join(' · '),state.party.map(p=>p.name).join(' · '),'party')}${card('🛂','ENTRY QR',`${state.party.filter(p=>state.entryQrs[p.id]).length} / ${state.party.length} 已準備`,'每位成員獨立保存 Visit Japan Web QR','entryqr')}${card('✅','DEPARTURE CHECKLIST',`${state.checklist.filter(x=>x.done).length} / ${state.checklist.length} 完成`,'出發前證件 / 自駕 / 親子檢查','checklist')}${card('📤','SHARE TRIP','分享行程','不含入境 QR / 保險 / 同行者個資','share')}<div class="box"><div class="boxHead"><div><small>FAMILY MODE</small><b>家庭節奏</b></div><span>👨‍👩‍👦</span></div>${[['toddler','幼童同行'],['elderly','長輩同行'],['stroller','攜帶推車'],['nap','保留午休'],['relaxed','不要排太趕']].map(([k,l])=>`<label class="toggle"><span>${l}</span><input type="checkbox" ${state.family[k]?'checked':''} data-change="app.family('${k}',this.checked)"></label>`).join('')}</div>${card('💰','BUDGET',`NT$ ${total.toLocaleString()}`,`預算 ${Number(state.meta.budgetTarget||0).toLocaleString()} · 剩餘 ${(Number(state.meta.budgetTarget||0)-total).toLocaleString()}`,'budget')}<div class="daysPick"><b>旅行天數</b><div>${[3,4,5,6,7,8,9,10].map(n=>`<button class="dayBtn ${state.days===n?'selected':''}" data-click="app.days(${n})">${n}</button>`).join('')}</div></div><div class="dataTools"><button class="btn outline small" data-click="app.exportData(false)">匯出行程</button><button class="btn outline small" data-click="app.exportData(true)">完整備份</button><label class="btn outline small">匯入資料<input type="file" accept="application/json" hidden data-change="app.importData(this.files[0])"></label><button class="btn danger small" data-click="app.clearLocalData()">清除本機資料</button></div><p class="tiny">「匯出行程」不含旅平險資料；「完整備份」會包含旅平險 Memo。入境 QR 永遠不會匯出。</p>`}
function mapView(){const t=trip(),stay=state.stays.find(s=>state.day>=Number(s.fromDay)&&state.day<=Number(s.toDay)),usable=t.flatMap((slot,si)=>slot.items.map((item,ii)=>({...item,slot:slot.name,si,ii}))).filter(x=>x.value&&x.value!=='待安排'&&x.value!=='飯店早餐');return `${dayTabs()}<div class="mapHero"><span class="mapPinIcon">📍</span><h2>DAY ${state.day} Route</h2><p>${stay?`已套用 DAY ${state.day} 住宿：${esc(stay.hotel)}`:`DAY ${state.day} 未設定住宿`}</p><button class="btn primary" data-click="app.route()">🧭 全日路線預覽</button></div><button class="stopBtn" data-click="app.route()"><b>${usable.length} STOPS</b><span>開啟 Google Maps</span><b>🧭</b></button><div class="nearbyBox"><b>附近快速搜尋</b><div class="nearbyGrid"><button class="btn secondary" data-click="app.nearby('toilet')">🚻 廁所</button><button class="btn secondary" data-click="app.nearby('convenience')">🏪 便利商店</button><button class="btn secondary" data-click="app.nearby('gas')">⛽ 加油站</button></div><span>會在你允許定位後開啟 Google Maps；拒絕定位時改搜尋沖繩全域。</span></div><div class="routeList">${usable.map((x,i)=>`<div class="routeRow"><span>${i+1}</span><div><small>${esc(x.slot)}${x.time?' · '+esc(x.time):''}</small><b>${esc(x.value)}</b></div><button class="btn secondary small" data-click="app.navTo('${encodeURIComponent(x.value)}')">🧭 導航</button></div>`).join('')}</div><p class="tiny">全日預覽最多帶入 3 個中途點；站點多時請使用逐站導航。</p>`}
