function exploreView(){const list=placeList(),on=state.explore.online;return `<div class="search"><span>🔎</span><input id="exploreQ" placeholder="搜尋景點、餐廳、地點…" value="${esc(state.explore.q)}" data-input="app.exploreQ(this.value)" data-keydown="if(event.key==='Enter')app.webSearch()"></div><div class="searchActions"><button class="btn secondary" data-click="app.webSearch()" ${state.explore.loading?'disabled':''}>🌐 ${state.explore.loading?'聯網搜尋中…':'聯網查詢'}</button><span>免費地點搜尋 · © OpenStreetMap contributors</span></div>${state.explore.error?`<div class="error">${esc(state.explore.error)}</div>`:''}${on?`<div class="online"><div class="onlineHead"><span>🌐</span><b>免費聯網地點</b></div><p>${esc(on.answer)}</p>${(on.places||[]).map((p,i)=>`<div class="webPlace"><div><small>${esc(regionOfArea(p.area))} · ${esc(p.type)} · ${esc(p.area)}</small><b>${esc(p.title)}</b><span>${esc(p.note)}</span></div><button class="btn secondary small" data-click="app.addWebPopular(${i})">＋ 熱門</button><button class="btn primary small" data-click="app.select('web${i}')">＋ 行程</button>${chooser('web'+i,{...p,meta:p.note})}</div>`).join('')}<div class="sources">${(on.sources||[]).map((s,i)=>`<button class="btn outline small" data-click="location.href='${esc(s.url)}'">↗ ${i+1}. ${esc(s.title)}</button>`).join('')}</div></div>`:''}<div class="chips">${['全部','北部','中部','南部','那霸市區','景點','美食','購物','雨天','親子'].map(x=>`<button class="chip ${fsel(x)}" data-click="app.filter('${x}')">${filterLabel(x)}</button>`).join('')}</div><div class="rowBetween"><div><b>熱門景點與美食</b><div class="tiny">${list.length} 個結果</div></div><div class="chips"><button class="chip" data-click="app.open('custom')">＋ 新增</button>${state.hidden.length?`<button class="chip" data-click="app.restorePlaces()">還原</button>`:''}</div></div><div class="placeList">${list.map(p=>`<div class="placeCard"><div class="emoji">${esc(p.emoji||'📍')}</div><div class="placeBody"><small>${esc(p.type)} · ${esc(p.area)}</small><b>${esc(p.title)}</b><span>${esc(p.meta)}</span></div><button class="iconBtn" data-click="app.mapSearch('${encodeURIComponent(p.query||p.title)}')">📍</button><button class="iconBtn" data-click="app.removePlace('${p.id}',${p.custom?'true':'false'})">🗑</button><button class="iconBtn primary" data-click="app.select('${p.id}')">＋</button>${chooser(p.id,p)}</div>`).join('')}</div>`}
function filterLabel(x){if(!['北部','中部','南部','那霸市區'].includes(x))return x;return x+' '+[...curated,...state.custom].filter(p=>regionOfArea(p.area)===x).length}
function fsel(x){return state.explore.filter===x?'selected':''}
function sosView(){return `<div class="sosHero"><span class="sosIcon">🆘</span><div><small>JAPAN EMERGENCY</small><h2>需要協助？</h2><p>119 救護/消防 · 110 警察 · 118 海上</p></div></div>${[['119','救護車・消防','🚑'],['110','警察・交通事故','👮'],['118','海上事故・海上保安廳','🚢']].map(([n,l,i])=>`<a class="emergency" href="tel:${n}"><span>${i}</span><div><b class="n">${n}</b><span>${l}</span></div><span>☎</span></a>`).join('')}<div class="sosGrid"><button class="btn secondary" data-click="app.locate()">📍 我的定位</button><button class="btn secondary" data-click="app.mapSearch('${encodeURIComponent('emergency hospital Okinawa')}')">🏥 最近急診</button><button class="btn secondary" data-click="app.mapSearch('${encodeURIComponent('police station Okinawa')}')">👮 最近警察</button></div>${state.location?`<div class="notice">📍 ${state.location.lat.toFixed(6)}, ${state.location.lng.toFixed(6)}</div>`:''}<div class="box insuranceBox"><div class="boxHead"><div><small>TRAVEL INSURANCE</small><b>旅平險 · 出險 Memo</b></div><span>🧾</span></div><div class="insuranceSummary"><span>保險公司</span><b>${esc(state.insurance.company||'尚未設定')}</b><span>海外急難</span><b>${esc(state.insurance.assistPhone||'尚未設定')}</b></div><button class="btn secondary full" data-click="app.open('insurance')">📋 出險流程 / 文件 / 我的 Memo</button></div><div class="box"><div class="boxHead"><div><small>JAPANESE HELP</small><b>日文求救卡 · 5 句</b></div><span>🗣️</span></div><div class="phraseCard"><strong>救急車を呼んでください。</strong><span>請幫我叫救護車。</span></div><div class="phraseCard"><strong>警察を呼んでください。</strong><span>請幫我叫警察。</span></div><div class="phraseCard"><strong>子どもがけがをしました。助けてください。</strong><span>小孩受傷了，請幫忙。</span></div><div class="phraseCard"><strong>病院に連れて行ってください。</strong><span>請帶我去醫院。</span></div><div class="phraseCard"><strong>中国語を話せる人はいますか？</strong><span>有人會說中文嗎？</span></div></div><div class="box"><div class="boxHead"><div><small>CHINESE SUPPORT</small><b>中文緊急資源</b></div><span>☎️</span></div><a class="resourceCard" href="tel:0570050235"><b>沖繩醫療中文諮詢</b><strong>0570-050-235</strong><span>24 小時 · 365 天 · 中文 / 台灣語等</span></a><a class="resourceCard" href="tel:05038162787"><b>JNTO Japan Visitor Hotline</b><strong>050-3816-2787</strong><span>24 小時 · 中文 · 疾病 / 事故 / 災害協助</span></a><a class="resourceCard" href="tel:%237119"><b>沖繩 #7119</b><strong>#7119</strong><span>不確定要不要叫救護車時 · 24 小時 · 中文</span></a><a class="resourceCard" href="tel:0988667119"><b>#7119 備用號碼</b><strong>098-866-7119</strong><span>無法撥 # 號碼時使用</span></a></div>`}
function render(preserveDraft=false){const drafts=preserveDraft&&state.modal?[...document.querySelectorAll('.sheet input[id],.sheet textarea[id],.sheet select[id]')].map(el=>({id:el.id,value:el.value,checked:el.checked})):[];let body=state.tab==='today'?today():state.tab==='trip'?tripView():state.tab==='map'?mapView():state.tab==='explore'?exploreView():sosView();$('#app').innerHTML=`<div class="app">${header()}${body}${publicFooter()}${nav()}</div>${modalHtml()}`;for(const d of drafts){const el=document.getElementById(d.id);if(el){el.value=d.value;if(el.type==='checkbox')el.checked=d.checked}}}
function modalHtml(){const m=state.modal;if(!m)return'';if(m.type==='slotItem'){const slot=trip()[m.si],item=m.ii===null?{value:'',meta:'',time:'',done:false}:slot.items[m.ii]||{value:'',meta:'',time:'',done:false},isNew=m.ii===null;return modal(`${isNew?'新增':'編輯'} ${slot.icon} ${slot.name}行程`,`<label class="field">行程名稱<input id="slotValue" value="${esc(item.value)}" placeholder="例如：teamLab Future Park Okinawa"></label><div class="grid2"><label class="field">時間（選填）<input id="slotTime" type="time" value="${esc(item.time)}"></label><label class="field">備註<input id="slotMeta" value="${esc(item.meta)}" placeholder="例如：室內親子 · 車程 12 分"></label></div><button class="btn primary full" data-click="app.saveSlotItem(${m.si},${isNew?'null':m.ii})">${isNew?'加入行程':'儲存修改'}</button>${isNew?'':`<div class="slotEditActions"><button class="btn outline" data-click="app.moveSlotItem(${m.si},${m.ii},-1)" ${m.ii===0?'disabled':''}>↑ 往前</button><button class="btn outline" data-click="app.moveSlotItem(${m.si},${m.ii},1)" ${m.ii===slot.items.length-1?'disabled':''}>↓ 往後</button></div><button class="btn danger full" data-click="app.deleteSlotItem(${m.si},${m.ii})">刪除此行程</button>`}`)}if(m.type==='flight')return modal('✈️ 航班設定',flightForm());if(m.type==='stay')return modal('🏨 住宿',stayForm());if(m.type==='transport')return modal('🚗 交通 / 租車',transportForm());if(m.type==='party')return modal('👨‍👩‍👦 同行者',partyForm());if(m.type==='entryqr')return modal('🛂 入境 QR · 所有成員',entryQrForm());if(m.type==='insurance')return modal('🧾 旅平險 · 出險 Memo',insuranceForm());if(m.type==='checklist')return modal('✅ 出發 Checklist',checklistForm());if(m.type==='share')return modal('📤 分享行程',shareForm());if(m.type==='qrview')return modal('🛂 入境 QR',qrViewForm(m.id));if(m.type==='budget')return modal('💰 旅費',budgetForm());if(m.type==='custom')return modal('＋ 新增熱門景點',customForm());if(m.type==='ai')return modal(`✨ SMART PLAN · ${state.days} 天`,aiForm());return''}
function modal(title,content){return `<div class="overlay" data-click="if(event.target===this)app.close()"><div class="sheet"><div class="sheetHead"><h3>${title}</h3><button class="iconBtn" data-click="app.close()">×</button></div>${content}</div></div>`}
function flightForm(){const r=(k,l)=>{const f=state.flights[k]||{};return `<div class="group"><b>${l}</b><div class="grid2">${field(`${k}_date`,'日期',f.date,'date')}${field(`${k}_flight`,'航班',f.flight)}${field(`${k}_from`,'出發機場',f.from)}${field(`${k}_to`,'抵達機場',f.to)}${field(`${k}_departTime`,'起飛',f.departTime,'time')}${field(`${k}_arriveTime`,'抵達',f.arriveTime,'time')}</div></div>`};return r('outbound','去程')+r('return','回程')+`<button class="btn primary full" data-click="app.saveFlight()">儲存航班</button>`}
function stayForm(){return `${state.stays.map((s,i)=>`<div class="group"><div class="rowBetween"><b>住宿 ${i+1} · Day ${s.fromDay}–${s.toDay}</b><button class="iconBtn" data-click="app.delStay(${i})">🗑</button></div>${field(`stay_${i}_hotel`,'飯店名稱',s.hotel)}<div class="grid2">${field(`stay_${i}_fromDay`,'入住 Day',s.fromDay,'number')}${field(`stay_${i}_toDay`,'住到 Day',s.toDay,'number')}</div>${field(`stay_${i}_address`,'地址',s.address)}${field(`stay_${i}_phone`,'電話',s.phone)}</div>`).join('')}<button class="btn secondary full" data-click="app.splitStays()">📅 按 DAY 拆分住宿</button><button class="btn secondary full" data-click="app.addStay()">＋ 新增住宿</button><button class="btn primary full" data-click="app.saveStays()">儲存住宿</button><p class="tiny">可設定 Day 1、Day 2… 每一天住不同飯店；也可用 Day 1–2 代表連住。</p>`}
function transportForm(){return `<div class="chips">${['自駕','大眾運輸','包車'].map(x=>`<button class="chip ${state.meta.transport===x?'selected':''}" data-click="app.setTransport('${x}')">${x}</button>`).join('')}</div>${field('rentalCompany','租車 / 包車公司',state.meta.rentalCompany)}<div class="grid2">${field('pickup','取車',state.meta.pickup)}${field('dropoff','還車',state.meta.dropoff)}</div><button class="btn primary full" data-click="app.saveTransport()">儲存交通</button>`}
function partyForm(){return `${state.party.map((p,i)=>`<div class="group"><div class="rowBetween"><b>同行者 ${i+1}</b><button class="iconBtn" data-click="app.delPerson(${i})">🗑</button></div><div class="grid2">${field(`p_${i}_name`,'姓名 / 暱稱',p.name)}${field(`p_${i}_age`,'年齡',p.age)}</div><div class="chips">${['成人','兒童','長輩'].map(x=>`<button class="chip ${p.type===x?'selected':''}" data-click="app.personType(${i},'${x}')">${x}</button>`).join('')}</div>${field(`p_${i}_notes`,'備註',p.notes)}</div>`).join('')}<button class="btn secondary full" data-click="app.addPerson()">＋ 新增同行者</button><button class="btn primary full" data-click="app.saveParty()">儲存同行者</button>`}
function entryQrForm(){const ready=state.party.filter(p=>state.entryQrs[p.id]).length;return `<div class="entryQrTop"><div><small>VISIT JAPAN WEB</small><b>已準備 ${ready} / ${state.party.length}</b><span>每位同行者各自保存 QR 圖片</span></div><a class="btn primary small" href="https://www.vjw.digital.go.jp/" target="_blank" rel="noopener">開官方網站 ↗</a></div><div class="qrMembers">${state.party.map((p,i)=>{const has=!!state.entryQrs[p.id];return `<div class="qrMember"><div class="rowBetween"><div class="qrWho"><small>MEMBER ${i+1}</small><b>${esc(p.name||('同行者 '+(i+1)))}</b><span>${esc(p.type)}${p.age?' · '+esc(p.age)+'歲':''}</span></div><span class="qrStatus ${has?'ready':''}">${has?'✓ 已儲存':'尚未加入'}</span></div>${has?`<button class="qrThumb" data-click="app.viewQr('${p.id}')"><img src="${state.entryQrs[p.id]}" alt="${esc(p.name)} 入境 QR"><span>點擊放大</span></button>`:`<div class="qrEmpty"><b>QR</b><span>上傳 Visit Japan Web QR 截圖</span></div>`}<div class="qrActions"><label class="btn secondary small">${has?'更換 QR':'＋ 上傳 QR'}<input type="file" accept="image/png,image/jpeg,image/webp" hidden data-change="app.uploadEntryQr('${p.id}',this.files[0])"></label>${has?`<button class="btn outline small" data-click="app.deleteEntryQr('${p.id}')">刪除</button>`:''}</div></div>`}).join('')}</div><p class="tiny">🔒 QR 圖片只儲存在這台裝置的瀏覽器 IndexedDB，不會上傳到 GitHub、Vercel，也不包含在「匯出資料」檔案裡。清除瀏覽器網站資料會一併刪除。</p>`}
function qrViewForm(id){const p=state.party.find(x=>x.id===id),src=state.entryQrs[id];return src?`<div class="qrFull"><small>${esc(p?.name||'旅客')}</small><img src="${src}" alt="入境 QR"><b>出示前請確認是正確成員</b></div>`:'<div class="error">找不到這張 QR。</div>'}
function insuranceForm(){return `<div class="claimAlert"><b>事故當下先做 4 件事</b><span>① 拍照 / 錄影　② 記錄時間地點　③ 索取官方 / 航空 / 醫療證明　④ 收據、登機證、行李條都保留</span></div><div class="grid2">${field('ins_company','保險公司',state.insurance.company,'text','例如：國泰 / 富邦')}${field('ins_policy','保單號碼',state.insurance.policyNo)}</div><div class="grid2">${field('ins_assist','海外急難電話',state.insurance.assistPhone,'tel')}${field('ins_claim','理賠電話',state.insurance.claimPhone,'tel')}</div>${field('ins_url','理賠網址 / App',state.insurance.claimUrl,'url')}<div class="claimCases"><div class="claimCase"><b>🏥 醫療 / 意外</b><span>留診斷證明、醫療收據、費用明細；重大治療或住院時，能聯絡海外急難協助就先聯絡。</span></div><div class="claimCase"><b>✈️ 班機延誤 / 取消</b><span>留機票 / 登機證、航空公司延誤或取消證明，以及額外交通、住宿、餐食單據。</span></div><div class="claimCase"><b>🧳 行李延誤 / 遺失</b><span>立即向航空公司報告並拿行李事故 / 延誤書面證明（PIR 類文件）；保留行李條與必要用品收據。</span></div><div class="claimCase"><b>🚨 竊盜 / 搶奪</b><span>盡快向當地警方報案並取得書面證明；列出遺失物，保留購買紀錄、照片或其他價值證明。</span></div></div><label class="field"><span>我的注意事項 / Memo</span><textarea id="ins_memo" rows="6" placeholder="例如：一家人的保單方案、信用卡附贈保險、客服說明、理賠上限…">${esc(state.insurance.memo)}</textarea></label><button class="btn primary full" data-click="app.saveInsurance()">儲存旅平險 Memo</button><p class="tiny">本機儲存；不要填信用卡完整卡號、密碼或身分證完整號碼。實際承保範圍、等待時間與文件仍以你的保單條款及保險公司要求為準。</p>`}
function checklistForm(){const done=state.checklist.filter(x=>x.done).length,groups=[...new Set(state.checklist.map(x=>x.group))];return `<div class="checkHead"><b>${done} / ${state.checklist.length} 完成</b><button class="btn outline small" data-click="app.resetChecklist()">重設</button></div>${groups.map(g=>`<div class="checkGroup"><small>${esc(g)}</small>${state.checklist.filter(x=>x.group===g).map(x=>`<button class="checkItem ${x.done?'done':''}" data-click="app.toggleChecklist('${x.id}')"><span>${x.done?'✓':''}</span><b>${esc(x.label)}</b></button>`).join('')}</div>`).join('')}<p class="tiny">Checklist 只存在這台裝置。護照、駕照譯本與保險等仍請以官方要求為準。</p>`}
function buildShareText(){const lines=['Okinawa Trip · '+state.days+' Days'];if(state.meta.startDate)lines.push('日期：'+state.meta.startDate+(state.meta.endDate?' ～ '+state.meta.endDate:''));const o=state.flights.outbound||{},r=state.flights.return||{};if(o.flight||r.flight)lines.push('航班：'+[o.flight&&('去 '+o.flight+' '+(o.departTime||'')),r.flight&&('回 '+r.flight+' '+(r.departTime||''))].filter(Boolean).join(' / '));if(state.stays.length)lines.push('住宿：'+state.stays.map(x=>'D'+x.fromDay+(x.toDay!==x.fromDay?'–'+x.toDay:'')+' '+(x.hotel||'未命名')).join('；'));for(let d=1;d<=state.days;d++){const slots=tripForDay(d),items=slots.map(slot=>{const xs=slot.items.filter(x=>x.value&&x.value!=='待安排').map(x=>(x.time?x.time+' ':'')+x.value);return xs.length?slot.name+'：'+xs.join(' → '):''}).filter(Boolean);if(items.length)lines.push('DAY '+d+'｜'+items.join('｜'))}lines.push('由 Okinawa Trip 規劃');return lines.join('\n')}
function shareForm(){return `<div class="sharePreview"><pre>${esc(buildShareText())}</pre></div><button class="btn primary full" data-click="app.shareTrip()">📤 系統分享</button><button class="btn secondary full" data-click="app.copyShareText()">📋 複製文字</button><button class="btn outline full" data-click="app.downloadShare()">⬇ 下載分享檔</button><p class="tiny">分享內容不包含入境 QR、旅平險資料，也不包含同行者姓名與年齡。</p>`}
function budgetForm(){return `${field('budgetTarget','總預算',state.meta.budgetTarget,'number')}<div class="grid2">${expenseNames.map(x=>field(`exp_${x}`,x,state.expenses[x]||'', 'number')).join('')}</div><button class="btn primary full" data-click="app.saveBudget()">儲存預算</button>`}
function customForm(){return `${field('custom_title','名稱','','text','例如：波上宮')}<div class="grid2">${field('custom_area','區域','','text','例如：那霸')}${field('custom_type','類型','景點')}</div>${field('custom_meta','備註','')}<button class="btn primary full" data-click="app.saveCustom()">加入熱門清單</button>`}
function aiForm(){if(state.ai?.result){return `<div class="notice">✨ ${esc(state.ai.result.summary)}</div>${state.ai.result.days.map(d=>`<div class="aiDay"><b>DAY ${d.day} · ${esc(d.theme)}</b>${['breakfast','morning','lunch','afternoon','dinner','evening'].map(k=>`<div><span>${k}</span><strong>${esc(d[k].value)}</strong><small>${esc(d[k].meta)}</small></div>`).join('')}</div>`).join('')}<button class="btn primary full" data-click="app.applyAI()">✓ 套用整趟 SMART 行程</button><p class="tiny">100% 本機產生，不呼叫 AI API；只覆蓋行程，不改航班、住宿、同行者與預算。</p>`}return `<label class="field">想去的地方 / 其他要求<textarea id="aiWishes" rows="4" placeholder="例如：美麗海、古宇利島、親子、不要太趕…"></textarea></label><p class="tiny">FREE Smart Plan 會依航班、住宿 Day 範圍、家庭模式與區域動線排程。完全本機運算，0 API 費、0 信用卡。</p><button class="btn primary full" data-click="app.generateAI()">✨ 產生免費智慧行程</button>`}
function field(id,label,value='',type='text',placeholder=''){return `<label class="field"><span>${label}</span><input id="${id}" type="${type}" value="${esc(value)}" placeholder="${esc(placeholder)}"></label>`}

function splitActionArgs(src){const out=[];let cur='',quote='',escp=false,depth=0;for(const ch of src){if(escp){cur+=ch;escp=false;continue}if(ch==='\\'){cur+=ch;escp=true;continue}if(quote){cur+=ch;if(ch===quote)quote='';continue}if(ch==="'"||ch==='"'){quote=ch;cur+=ch;continue}if(ch==='('||ch==='['||ch==='{'){depth++;cur+=ch;continue}if(ch===')'||ch===']'||ch==='}'){depth--;cur+=ch;continue}if(ch===','&&depth===0){out.push(cur.trim());cur='';continue}cur+=ch}if(cur.trim())out.push(cur.trim());return out}
function actionValue(v,el){v=v.trim();if(v==='this.checked')return !!el.checked;if(v==='this.value')return el.value;if(v==='this.files[0]')return el.files?.[0];if(v==='true')return true;if(v==='false')return false;if(v==='null')return null;if(v==='undefined')return undefined;if(/^-?\d+(?:\.\d+)?$/.test(v))return Number(v);if((v.startsWith("'")&&v.endsWith("'"))||(v.startsWith('"')&&v.endsWith('"')))return v.slice(1,-1).replace(/\\'/g,"'").replace(/\\"/g,'"').replace(/\\\\/g,'\\');return v}
function dispatchAction(code,event,el){if(!code)return;if(code==="if(event.key==='Enter')app.webSearch()"){if(event.key==='Enter'){event.preventDefault();app.webSearch()}return}if(code==='if(event.target===this)app.close()'){if(event.target===el)app.close();return}const lm=code.match(/^location\.href='([^']*)'$/);if(lm){location.href=lm[1];return}const m=code.match(/^app\.([A-Za-z0-9_]+)\((.*)\)$/);if(!m)return;const fn=app[m[1]];if(typeof fn!=='function')return;const args=m[2].trim()?splitActionArgs(m[2]).map(v=>actionValue(v,el)):[];return fn(...args)}
function bindActions(){const root=$('#app');if(!root||root.dataset.bound)return;root.dataset.bound='1';root.addEventListener('click',e=>{const el=e.target.closest('[data-click]');if(el&&root.contains(el))dispatchAction(el.dataset.click,e,el)});root.addEventListener('change',e=>{const el=e.target.closest('[data-change]');if(el&&root.contains(el))dispatchAction(el.dataset.change,e,el)});root.addEventListener('keydown',e=>{const el=e.target.closest('[data-keydown]');if(el&&root.contains(el))dispatchAction(el.dataset.keydown,e,el)});root.addEventListener('input',e=>{const el=e.target.closest('[data-input]');if(el&&root.contains(el))dispatchAction(el.dataset.input,e,el)})}

